-- 목적: book_text 페이지 단위 본문 적재 (bd_html · 이 파일: 1of1)
-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D9~D12) · Accepted 2026-08-10
-- source 라벨: html_scene_json_v1
-- 이 파일 담당: 39권 / 469행 (정제 후 빈 면 1행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='book_dash' AND b.source_id IN ('9c9e55de-fe46-11e5-86aa-5e5517507c66', '9c9e596c-fe46-11e5-86aa-5e5517507c66', '9c9e5f48-fe46-11e5-86aa-5e5517507c66', '9c9e6196-fe46-11e5-86aa-5e5517507c66', '9c9e62ea-fe46-11e5-86aa-5e5517507c66', '9c9e640c-fe46-11e5-86aa-5e5517507c66', '9c9e6524-fe46-11e5-86aa-5e5517507c66', '9c9e663c-fe46-11e5-86aa-5e5517507c66', '9c9e6754-fe46-11e5-86aa-5e5517507c66', '9c9e6d12-fe46-11e5-86aa-5e5517507c66', '9c9e6e52-fe46-11e5-86aa-5e5517507c66', '9c9e6f9c-fe46-11e5-86aa-5e5517507c66', '9c9e71cc-fe46-11e5-86aa-5e5517507c66', '9c9e72e4-fe46-11e5-86aa-5e5517507c66', '9c9e76ea-fe46-11e5-86aa-5e5517507c66', '9c9e7820-fe46-11e5-86aa-5e5517507c66', '9c9e7a6e-fe46-11e5-86aa-5e5517507c66', '9c9e7b9a-fe46-11e5-86aa-5e5517507c66', '9c9e7cb2-fe46-11e5-86aa-5e5517507c66', '9c9e7dca-fe46-11e5-86aa-5e5517507c66', '9c9e819e-fe46-11e5-86aa-5e5517507c66', '9c9e83b0-fe46-11e5-86aa-5e5517507c66', '9c9e8586-fe46-11e5-86aa-5e5517507c66', '9c9e86da-fe46-11e5-86aa-5e5517507c66', '9c9e87f2-fe46-11e5-86aa-5e5517507c66', '9c9e8c0c-fe46-11e5-86aa-5e5517507c66', '9c9e9102-fe46-11e5-86aa-5e5517507c66', '9c9e9396-fe46-11e5-86aa-5e5517507c66', '9c9e94e0-fe46-11e5-86aa-5e5517507c66', '9c9e96ac-fe46-11e5-86aa-5e5517507c66', '9c9e9e5e-fe46-11e5-86aa-5e5517507c66', '9c9e9fc6-fe46-11e5-86aa-5e5517507c66', '9c9ea21e-fe46-11e5-86aa-5e5517507c66', '9c9ea48a-fe46-11e5-86aa-5e5517507c66', '9c9ea96c-fe46-11e5-86aa-5e5517507c66', '9c9eb2cc-fe46-11e5-86aa-5e5517507c66', '9c9eb68c-fe46-11e5-86aa-5e5517507c66', '9c9f3292-fe46-11e5-86aa-5e5517507c66', '9c9f566e-fe46-11e5-86aa-5e5517507c66');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 39
SELECT count(*) AS books_found FROM books
  WHERE source_platform='book_dash' AND source_id IN ('9c9e55de-fe46-11e5-86aa-5e5517507c66', '9c9e596c-fe46-11e5-86aa-5e5517507c66', '9c9e5f48-fe46-11e5-86aa-5e5517507c66', '9c9e6196-fe46-11e5-86aa-5e5517507c66', '9c9e62ea-fe46-11e5-86aa-5e5517507c66', '9c9e640c-fe46-11e5-86aa-5e5517507c66', '9c9e6524-fe46-11e5-86aa-5e5517507c66', '9c9e663c-fe46-11e5-86aa-5e5517507c66', '9c9e6754-fe46-11e5-86aa-5e5517507c66', '9c9e6d12-fe46-11e5-86aa-5e5517507c66', '9c9e6e52-fe46-11e5-86aa-5e5517507c66', '9c9e6f9c-fe46-11e5-86aa-5e5517507c66', '9c9e71cc-fe46-11e5-86aa-5e5517507c66', '9c9e72e4-fe46-11e5-86aa-5e5517507c66', '9c9e76ea-fe46-11e5-86aa-5e5517507c66', '9c9e7820-fe46-11e5-86aa-5e5517507c66', '9c9e7a6e-fe46-11e5-86aa-5e5517507c66', '9c9e7b9a-fe46-11e5-86aa-5e5517507c66', '9c9e7cb2-fe46-11e5-86aa-5e5517507c66', '9c9e7dca-fe46-11e5-86aa-5e5517507c66', '9c9e819e-fe46-11e5-86aa-5e5517507c66', '9c9e83b0-fe46-11e5-86aa-5e5517507c66', '9c9e8586-fe46-11e5-86aa-5e5517507c66', '9c9e86da-fe46-11e5-86aa-5e5517507c66', '9c9e87f2-fe46-11e5-86aa-5e5517507c66', '9c9e8c0c-fe46-11e5-86aa-5e5517507c66', '9c9e9102-fe46-11e5-86aa-5e5517507c66', '9c9e9396-fe46-11e5-86aa-5e5517507c66', '9c9e94e0-fe46-11e5-86aa-5e5517507c66', '9c9e96ac-fe46-11e5-86aa-5e5517507c66', '9c9e9e5e-fe46-11e5-86aa-5e5517507c66', '9c9e9fc6-fe46-11e5-86aa-5e5517507c66', '9c9ea21e-fe46-11e5-86aa-5e5517507c66', '9c9ea48a-fe46-11e5-86aa-5e5517507c66', '9c9ea96c-fe46-11e5-86aa-5e5517507c66', '9c9eb2cc-fe46-11e5-86aa-5e5517507c66', '9c9eb68c-fe46-11e5-86aa-5e5517507c66', '9c9f3292-fe46-11e5-86aa-5e5517507c66', '9c9f566e-fe46-11e5-86aa-5e5517507c66');

-- ───────── [적재] ─────────
BEGIN;
INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$html_scene_json_v1$$
  FROM (VALUES
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 0, $$Little Ant loved to read. Little Ant was often teased. “Ants don’t read. Ants must feed. Ants collect the food they need. ”$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 1, $$Little Ant would read all day, he’d read and read the day away. The other ants took what they found to store for winter underground.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 2, $$His mum and dad got really mad, and Little Ant felt really bad.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 3, $$In autumn when the leaves fall down, the ants must keep food underground.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 4, $$The Queen wants food to fill the store, so all the ants must work some more.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 5, $$Little Ant begins to shout about a place he read about. “A restaurant is what we need, a place where people go to feed. It says so in the books I read. ”$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 6, $$The ants go marching one by one. They march into the setting sun.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 7, $$And Little Ant said “Hey, there’s one! ”$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 8, $$The ants go marching one by one, carrying a burger, carrying a bun.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 9, $$When they return the Queen is glad. The stores are full. They cheer like mad.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 10, $$Ant gets hugs from mum and dad.$$),
    ('9c9e55de-fe46-11e5-86aa-5e5517507c66', 11, $$His baby sister takes his hand “Now I think I understand. ” “The way you love to read a book … Makes me want to take a look. ”$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 0, $$One day a very clever baby was born in Gungululu in the Eastern Cape. Her name was Sindiwe Magona. She was the oldest of eight children.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 1, $$At night, her grandmother told magical stories about ogres and giants, animals of the forests, great beasts, and little creatures of the veld. It was Sindiwe’s favourite time.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 2, $$Sindiwe loved school and she dreamed about being a teacher.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 3, $$When Sindiwe became a teenager, her family organised a feast to celebrate. She was given special things to wear and a wise old man sang a praise song to her. (Blessings, long life! May your ancestors guard you!)$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 4, $$Sindiwe trained to be a teacher. She was very excited to teach at her first school. But there weren’t enough schools for black children and they had no desks or books to write in. This made Sindiwe feel scared. How could she be a good teacher when the children had nowhere to sit?$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 5, $$She left the school to work as a cleaner. She worked in four different houses. Sometimes the people there treated her badly and Sindiwe became very unhappy.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 6, $$All this time Sindiwe studied. Her hard work paid off! She won a scholarship to study at a university in New York. She and her three small children packed their bags and flew across the sea to the United States of America.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 7, $$In New York, Sindiwe studied to become a social worker. She wanted to help families make their lives better.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 8, $$When she finished studying, the United Nations gave Sindiwe a job. Most of the countries in the world meet at the United Nations to talk about their problems.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 9, $$Sindiwe told the world about South Africa, and how hard it was for black people living there. The people at the United Nations loved to listen to Sindiwe’s stories. They wanted to learn more and more about South Africans. Perhaps, together, they could help to change things in South Africa.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 10, $$She worked at the United Nations for twenty years while her children grew into adults. But Sindiwe missed the country where she was born. She wanted to tell her stories to the people at home. So she packed her luggage, got on a plane and flew back over the sea to Cape Town.$$),
    ('9c9e596c-fe46-11e5-86aa-5e5517507c66', 11, $$Sindiwe’s love for books and stories have helped her write piles and piles of books. And children and grown-ups love to read her stories. Many people call her Nomabali because she’s always writing, telling and reading stories.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 0, $$Nita’s hanging upside down, her long hair tickling at the ground. The trees, the grass, the everything is all the wrong way round.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 1, $$Her feet, they poke into the sky. Little Navi’s walking by. He says ‘I’ve seen you here before. You’re upside down again! What for? ’$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 2, $$His feet swim lightly in the air. She tries to hide behind her hair. ‘It’s h-h-h-hard to t-t-talk’, she says to him. ‘I’m not the same. I don’t fit in.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 3, $$Navi takes her by the hand. He wants to help her understand. They climb to Navi’s look-out spot. From up here they can see a lot. They perch and have a quiet stare at children playing here and there.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 4, $$There are children playing on a slide, swings, a seesaw and a merry-go-round.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 5, $$Those kids are not the same at all. Abe’s round. Chi’s freckled.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 6, $$Lala’s extra tall.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 7, $$Bambam’s wild and must be free, while Lulu’s reading quietly.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 8, $$Look at Freya’s crazy hair.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 9, $$And Sid wears glasses everywhere.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 10, $$And me, I am just skin and bone. And you are you. You’re not alone. Each human’s sort of strange, you see. That makes you just the same, like me. This world is really one big game. To play, we can’t all be the same.$$),
    ('9c9e5f48-fe46-11e5-86aa-5e5517507c66', 11, $$Nita feels the right way round, thanks to the new friend she’s found. Upside down was never fun. Now she plays with everyone.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 0, $$Meet my friend Helen. She was born in a little Karoo town called Nieu Bethesda. There was not much going on in this town. But she made a whole world here. She even made me. And she named her house after me. It was called ‘The Owl House’.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 1, $$Most of Helen’s nine brothers and sisters were grown up and gone by the time she arrived. But she still had her sisters Annie and Alida. Helen didn’t have many friends in the village, but she didn’t mind. From the start, Helen did things differently from most people.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 2, $$After her sisters left home, Helen lived alone with her parents. She loved her mother, but she hated her father. Everyone agreed he was a very strange man. Her big sister Alida travelled all over the world. One day she sent Helen a postcard from Egypt. In her mind Helen saw princes and pyramids and camels in the sand.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 3, $$As she grew older, Helen read more stories of faraway places. She especially liked poems from Persia in the Middle East. She dreamed of visiting the ocean one day. She kept a seashell on her bedside table, and imagined she could hear the sound of waves inside it. But of course, owls were always her favourite things of all!$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 4, $$Helen loved books and stories so much that she decided to become a teacher. She was very good at it too. But then she met Johannes Pienaar. He was also a teacher, and a writer and actor. He convinced her to run away with him.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 5, $$Helen and Johannes got married. They travelled to many different towns, teaching and performing plays. Helen thought she might start a family like her sisters had done. But it was not to be. She and her husband were always fighting. When Helen’s mother became very sick, she decided it was time to go back home.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 6, $$Helen was not happy. Her mother was so sick, and her father was so grumpy. She kept to herself. People thought she was strange. The night her mother died, Helen kept a candle burning beside her bed all night. With the help of that little light, Helen didn’t feel so afraid of the dark.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 7, $$Helen decided she wanted brightness in her life. She began by changing the space around her. She needed helpers. Three men from the village, Jonas Adams, Piet van der Merwe, and Koos Malgas, made the things she imagined out of wire and cement. She filled her back garden with interesting creatures. There were sphinxes and camels, mermaids and cats. And lots and lots of owls! She called it her camel yard. On the fence she made a wire sign. It said: ‘This is my world’.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 8, $$During the day Helen made sculptures. At night, she practised catching light. She collected glasses and mirrors, candles and lamps. Anything that would shine. She put lanterns in every room. Mirrors caught and reflected the light. She covered the walls in glittering glass so that they could shine too. After Helen’s father died, she had the house to herself. Each night she slept in a different room. She would always choose the one with the best view of the moon and the stars.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 9, $$The people of Nieu Bethesda would walk past Helen’s garden and marvel at the creatures in it. Some of the village children brought her glass bottles for her sculptures and called her ‘Miss Helen’. She always thanked them with sweets. Others were not so friendly. They called her names and threw stones on her roof. Miss Helen spent all her money on glass and cement. She lived on bread and black tea. In her diary she wrote: “In my loneliness I am happy. ”$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 10, $$The garden grew and grew, until there was hardly space left for any more creatures. Miss Helen was tired now. Her hands were stiff and sore. Her eyes were going blind from working with tiny bits of glass. She wasn’t afraid of being alone. But she was still afraid of the dark. And her world was getting darker and darker. She knew that soon she wouldn’t be able to see anything at all.$$),
    ('9c9e6196-fe46-11e5-86aa-5e5517507c66', 11, $$But when she closed her eyes for the last time, Miss Helen didn’t see darkness. She saw the sun and the moon and the stars. She saw wise men and mermaids, camels and cats, acrobats and owls with big brown glittering glass eyes. And we still stand here today, just the way she left us, in the garden she made, looking East.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 0, $$A long time ago, in the vast city of Johannesburg, a baby girl was born. That baby was me. My mom called me Miriam. Miriam Makeba.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 1, $$Mom was a sangoma, but she also worked to make other people’s homes neat and clean. It was hard for my mom to earn enough for both of us. She started selling homemade beer to bring in more money.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 2, $$The laws of the land said that selling homemade beer was wrong. The police sent my mom to jail for six long months. I was only 18 days old, and needed my mom. So even though I was just a baby, I went to jail too.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 3, $$As a little girl I loved to sing. When I was older, I helped my mom clean houses. Singing songs as I worked made the chores go faster and the days seem brighter. Singing made me happier than I can explain.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 4, $$I sang in my church, and this made others happy too. Music has the power to bring people together. When we were singing we felt brave and strong.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 5, $$People said my voice was a gift and my songs were special. I sang with other musicians and our music was heard all over the world.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 6, $$My home was Sophiatown, a place of culture and music. Sophiatown, a place where South Africans could make music in harmony and dance together. But the people who ruled the land at the time did not like this togetherness. Those rulers didn’t want black and white people to be friends.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 7, $$I knew it was wrong to treat people differently because of their skin colour. I did not hide my beliefs, and so those people in charge wanted me out of the country. When I was singing in America, I was told I could never return home.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 8, $$People all over the world heard my story. My songs and my story helped many to see how there was no fairness in South Africa for those with black skin. I decided to go on singing and telling the truth about my country, no matter what.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 9, $$The world loved my music and I was welcomed in many countries. I won awards and sang for important people all over the globe. My life was good, but something was missing. I could not sing in my home country, and people there were not free.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 10, $$Then a wonderful day dawned when Nelson Mandela became president of South Africa. New people were in charge and the unfair laws belonged to the past. I finally went home with new hope in my heart.$$),
    ('9c9e62ea-fe46-11e5-86aa-5e5517507c66', 11, $$After that I could sing in a free, fair country. People of different skin colours could enjoy music together. I helped make this happen because I was brave and strong. I sang the truth in all of my songs.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 0, $$Basetsana Makgalemele was born in a township called Soweto. She was her parents’ third daughter. They named her Basetsana, which means “girls”. In Tswana culture, calling your daughter that means your next child will be a boy. This actually happened. Her parents’ next child was a boy. Her parents, big sisters and younger brother all called her Bassie for short.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 1, $$When she was a child, Bassie was very shy. She liked to sing and dance in her room on her own. One day at school netball practice, the coach told two girls to pick teams. Bassie stood on the edge of the field hoping someone would say, “Come play with us! ” But nobody wanted her on their team. Little did they know, Bassie would become one of the most popular girls in the country.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 2, $$On weekends, she and her brother and sisters helped their teacher mom and bus driver dad to pay the bills. They made sandwiches to sell at local soccer matches. They tried to sell everything as fast as they could so they had time to play with the other children when the game was over.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 3, $$By the time Bassie turned 16, she was a beautiful young woman. She was so beautiful that she won two beauty competitions in one year: Miss Soweto and Miss Black South Africa. But Bassie was not only beautiful on the outside. She was also beautiful on the inside. Even though she was a beauty queen, she still cared about the community where she grew up.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 4, $$Bassie was also very smart. She worked hard at school, especially on her favourite subject: science. Her hard work was rewarded when she was the top science student at her school in matric. That’s not all, she was also Head Girl. The shy little girl was now one of the most popular girls in school.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 5, $$Bassie’s father always encouraged his children to read. He gave her a book called The Power of Positive Thinking. From that book, she learnt that being optimistic is the key to making your dreams a reality. She dreamt of winning Miss South Africa. Not only did that dream come true, she was even crowned First Princess in the Miss World competition!$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 6, $$Bassie’s mother was her role model. Bassie described her mom as a “fierce, hardworking Xhosa woman who did not suffer fools”. She was a teacher and Bassie had plans to follow in her footsteps, but things don’t always go as planned! After winning Miss South Africa, she became a TV presenter. She wasn’t a teacher, but like her mom, she was hardworking. Her career in TV led to her opening her own television production company. She was now a successful business woman.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 7, $$Bassie’s motto is: “To whom much is given, much is expected. ” She believes that you are given a gift so that you can give to others. Bassie does this by volunteering, giving of her time and money and even creating jobs. She is involved with projects and charities to help people in her community. One that is very close to her heart is the Nelson Mandela Institute.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 8, $$Bassie had a very close relationship with Nelson Mandela. When she was crowned Miss South Africa, Madiba wrote her a letter of congratulations. In the letter, he called her “our Queen”. They shared a passion for children and education and the belief that an educated nation can help fight poverty.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 9, $$In 2002, Bassie married Romeo Kumalo and became known as Basetsana Kumalo. Together they established the Romeo & Basetsana Kumalo Family Foundation. The foundation looks after orphans - children who don’t have a mom and dad.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 10, $$Bassie has had to learn to balance her busy work and family life. She has her own company called Basetsana Women Investment Holdings. She and Romeo have three children, two boys and a girl. Bassie sees her role as mother to her children as her “highest calling and greatest privilege”.$$),
    ('9c9e640c-fe46-11e5-86aa-5e5517507c66', 11, $$Bassie says the secret to her success is “courage, determination, passion and staying committed to the course”. Despite all her success, she remains humble while trying to make the world a better place. Being beautiful on the outside is not what makes you a beautiful person. It’s a heart filled with love and generosity. And that’s why Bassie is our beautiful Queen.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 0, $$The children were talking about their Grandpas.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 1, $$My Grandpa can build a tower to the sky, said Giraffe. Once he built a skyscraper for a king.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 2, $$My Grandpa can fish for anything in the sea, said Cheetah. Once he caught a whale and kept it in his bath.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 3, $$My Grandpa can climb to the clouds in the sky, said Mountain Goat. He climbed the tallest mountain in the world, in just four hours.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 4, $$My Grandpa can cook a feast, said Elephant. Once he cooked a meal for a president’s birthday party. All by himself.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 5, $$Well my Grandpa doesn’t build or fish or climb or cook, said Monkey. But he owns gold! He hides it in his mouth. And at night he soaks it in a glass of water.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 6, $$No, he doesn’t! Yes, he does! No, he doesn’t! Well, come and see if you don’t believe me, said Monkey.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 7, $$So the children went to see Monkey’s Grandpa.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 8, $$You see? said Monkey. And he can take them out.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 9, $$No, he can’t! cried the animals.$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 10, $$Waaah! said Grandpa Monkey. And there are enough …$$),
    ('9c9e6524-fe46-11e5-86aa-5e5517507c66', 11, $$… for everyone!$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 0, $$One harsh winter, many people in the land were sick. Ma Monikazi’s cheeks burned. Sweat dripped from her body. She wanted to hold the icy grass to her face to cool down. Under her blanket she held her belly and sang to the baby inside her: “Be strong, little one. Winter’s not long. Be brave, little one. Together we’re strong! ” Her stomach growled when the baby’s powerful kicks woke her at night. She ate the leftover meat in the cooking pot, hungry for life. One bright night the moon was bigger, fatter and pinker than ever. Her breath came fast. The baby was ready. The aunties in the birthing room rubbed her back and warmed the water. When Monikazi held her beautiful daughter in her arms, she knew she was a special girl, a fighter. What a blessing! Her name is Nontsikelelo. She will be the mother of all blessings.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 1, $$Nontsikelelo was beautiful and strong with crinkling black button eyes. She loved her older brother, Mcengi. He made her laugh and so the laughter spread. She loved to eat meat before she had teeth. Her favourite aunt always kept a little portion on the side of her plate for Ntsiki. Mcengi chased the chickens that scratched in the garden where Ma Monikazi grew spinach and squash to feed her family. Ntsiki ran after him as her legs grew strong. Ma Monikazi had another baby boy, Velaphi, and another, Qudalele. Finally another sister, Nomyaleko. Little Ntsiki folded napkins and washed the baby clothes. She swept the house and fed the fire. She picked up her baby brother when he cried and tickled him till he laughed. She taught them to sing: “Be strong, little one. Winter is gone. Be brave, little one. Together we’re strong! ”$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 2, $$Qingqiwe, her grandfather, raised horses. His favourite was Shishi, a glossy black mare. As soon as Ntsiki was old enough, he hoisted her on to the saddle in front of him. His strong arms reached around her. He laced the reins through her fingers. He taught her to talk softly to Shishi, to groom her with a hard bristled brush. When she stroked its glossy coat, Albertina whispered, “You are the most beautiful creature. Thank you for letting me ride on your back. ” Her father, Bonilizwe, came home from the mines at Christmas. Ntsiki pulled herself up onto Shishi’s broad back. She rode out to meet him at the bus stop. Ntsiki sat tall and straight. Her knees held firm. She handled the reins with gentle fingers. How proud Bonilizwe was of his daughter. The biggest smile Ntsiki had ever seen covered her father’s face.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 3, $$On her sixth birthday she went to school. “You must choose an English name,” said the Presbyterian teacher, but Ntsiki liked her own name. “Why do I need a new name? ” she asked. The teacher scowled and read the names aloud: “Adah, Agnes, Albertina, Anna. ” What did they mean? Ntsiki liked the long name best. Al-ber-ti-na! The name had rhythm. Al-ber-ti-na! The name had bounce. Albertina was a name you didn’t mess with. When her cousin married a handsome man from a nearby town, Albertina was chosen as an umkhapi. The maid of honour! Weeks before the wedding, she stitched her isikhakha, the short traditional skirt, and threaded bright beads onto her amatikiti. Her mother gave her the white flag and said, “You have a big job, my blessing. ” At the bend in the road Albertina waved the flag, then turned Shishi back, leading everybody from miles around to the ceremony. People would gossip if she made a mistake, but the guests lined the road. They ululated and sang. They threw down flowers for the horse and the girl.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 4, $$Her mother was often sick and needed Albertina to look after the home. In her last year of primary school, Albertina was the oldest pupil in the school. She was chosen to be the head girl and wore her badge with pride. Her best friend, Betty, told her about a competition, saying, “You must apply, my clever friend. ” “What is the prize? ” asked Albertina, growing curious. “A scholarship to high school! ” said Betty. “You must apply. You’ll win it, for sure. ”Albertina studied until the candle burned down. She practised sums. She practised spelling. She sharpened her pencils and gave her shoes an extra shine. Next morning she passed Shishi in her paddock. The horse whinnied and stamped the ground.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 5, $$The test began. Albertina’s fingers shook. The sums were tricky. Her mouth went dry. Her hand cramped on her pencil but she continued. “Well done, Albertina! ” said her teacher at the end. The important official arrived and called the top two students to the stage. “Well done to Albertina for full marks,” he said, “but you are too old. The scholarship goes to…” Albertina tried not to cry. “That’s unfair,” shouted Betty, hopping with fury. “That wasn’t in the rules! ” How would Albertina go to high school now? She dragged her feet all the way home. The teacher wrote to the newspaper about the unfair decision. Brother Joe at the Catholic Mission station read the story over his breakfast. He cracked his boiled egg with an extra flourish. He pushed the newspaper across the table to Father Bernard. He didn’t like the story one bit either.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 6, $$Soon enough there was a scholarship for Albertina. Mariazell near Matatiele was a long way from Xolobe, but the whole village erupted. Their home girl was off to high school. She would make them proud. They threw a party like no other. The women brewed the sorghum beer and lit the fires. They slaughtered chickens and stirred up pots of meat. Albertina smiled till her face ached. She packed her brown suitcase and polished her shoes again. Before setting off on the bus to Matatiele, she said goodbye to Shishi. Albertina brushed her coat and stroked her wiry mane. She whispered all her questions into the horse’s silky ear: What if I get lost? Will I make new friends? Will I still be clever so far from home? Shishi whinnied and stamped the ground.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 7, $$School days started well before sunrise. The girls washed quickly in the cold water and swept the dormitories before Mass. The milky porridge was never quite enough; the stew not as tasty as Aunty’s back home. But Albertina studied hard. She played netball on sunny afternoons. In her school holidays Albertina worked at the mission station. She rubbed and scrubbed against the zinc washboard. She boiled sheets in copper tubs, then wound them through the wringer. She hoed and tilled the school garden but missed her family. Who was telling her brothers and sisters funny stories? Who wiped their eyes when they cried? Who tickled them until they laughed? Albertina loved the nuns who taught her. Could she become a holy sister? “But nuns earn no salary,” said Father Bernard. “Perhaps you should become a nurse? You’ll be paid while you study. ”$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 8, $$Albertina took a train to Johannesburg. She bought a smart white uniform, new navy shoes and a shiny red fountain pen. Sick people came all day to the hospital. She cleaned their wounds with careful fingers. She held the old people gently. When the babies cried, she sang: “Be strong, little one. Winter’s not long. Be brave, little one. Together we’re strong! Some nights Albertina worked till dawn. She looked out the window and thought of her family. Were the children hungry? Did they go to school? Who was riding Shishi? She remembered the dark green spinach. She missed the scent of the earth. There was no vegetable garden here. There was nowhere for a horse. Albertina never went to parties. She saved every shilling. On her days off she learned to play tennis. Whoosh! Plop! She whacked the ball across the net. Always, she wished for a little more money to send home.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 9, $$Walter Sisulu was a brave and clever man who dreamed of freedom for South Africa. His big smile captured Albertina’s eye. They walked together down the city streets. Her delicate hand rested on his arm. Walter wanted Albertina to be the mother of his children. Bright ribbons decorated the Bantu Men’s Social Centre on their wedding day. Albertina’s long-sleeved dress had a swirling train of lace. Many friends blessed their special day. Albertina planted flowers in her little garden. Within a year, Max was born. Albertina had become a mother. One day people would call her the mother of the nation. Max had his mother’s black button eyes and his father’s round chin. He was the hope for their future. Albertina wanted to fight for a new South Africa, so that Max could be free. When he cried, she sang: “Be strong, little one. Winter’s not long. Be brave, little one. Together we’re strong! ”$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 10, $$Police came in the middle of the night, banging on the door. Albertina scolded the men who messed up her house. “How rude you are! ” she said, “trampling mud inside my home. ” In the morning Albertina’s favourite flowers lay crushed beneath their footprints. She remembered chasing the chickens from her vegetable garden back in Xolobe and set about replanting her garden. The earth, she knew, would recover. She would support her husband who kept many secrets and hid from the police.$$),
    ('9c9e663c-fe46-11e5-86aa-5e5517507c66', 11, $$She joined the women and worked to organise a march to Pretoria. The women refused to carry a pass. They sang, “Wathint’ abafazi; wathint’ imbokodo! You strike a woman; you strike a rock! ” Many hard years followed after Walter’s arrest. He was jailed on Robben Island for 26 years. Albertina, also, was sent to jail many times. Often she was scared. Often she was lonely. But even on the darkest nights, she could see a sliver of moon through the window in her cell. She sang the song that Ma Monikazi sang before she was born: “Be strong, little one. Winter’s not long. Be brave, little one. Together we’re strong! ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 0, $$One special Friday Yusuf’s father gets dressed before a flicker of light brightens the sky. He pulls on his heavy weather-proof jacket and the green woollen cap that covers his ears. He waves his boy goodbye. Yusuf’s eyes brighten when Papa says, “Today is the day I will catch a fish and bring a gift home for you. ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 1, $$A fish and a gift? Oh, what will it be? Papa cycles down to Muizenberg Beach. Squeak squeak go the wheels all the way to Surfer’s Corner. Gulls circle the sky. “Whaaat? Whaaat? Whaaat? ” they cry. “What will you bring back for Yusuf? ” Papa rings his bell. “Wait and see what it will be! ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 2, $$The fishermen watch the sun rise. They check their nets. They check their oars. They listen to the wind. They drag their boats down to the water. Yusuf’s grandfather, Oupa Salie was a treknet fisherman. Before him his father, Oupagrootjie Ridwaan, knew the sea too.$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 3, $$The boat rides into the waves. Papa’s arms stretch to the oar. His leg braces against the side. His neck strains, his back muscles ripple. Papa sings as he works: “Drop and swish. Find a fish. Pull and plop. Don’t you stop. ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 4, $$All day long Yusuf looks at the sky. It is bright and clear and windless. A fish and a gift! What will Papa bring home from the sea? Sometimes he brings a beautiful shell. Sometimes he brings a jewel green bottle rinsed by the waves.$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 5, $$Some days Yusuf’s father brings a story. Like the time they found sea turtles on the sand, hundreds washed up in a storm. “Whaaat? Whaaat? Whaaat? ” cried the gulls. “What will you do to help the turtles? ” Papa said, “We saved those turtles, I tell you straight. We sent them back to the ocean, every last one. ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 6, $$Always Papa brings a song. He sings the song while he pulls the oars. He sings the song while he pulls the nets. He sings the song as he winds the ropes. He sings the song as he cycles home. “Drop and swish. Find a fish. Pull and plop. Don’t you stop. ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 7, $$Ouma Safiya wants a nice fat yellowtail for her supper. Mother wants a new dress. “Don’t be silly,” says Ouma. “You’ll be lucky if they catch even a tiny crab. More likely it will be fish tail Friday. There’s not so many fish left in the sea. ” Yusuf holds Ouma’s hand. They cross the road at the bathing cabins. “Whaaat? Whaaat? Whaaat? ” cry the gulls perched on the bright rooftops. “What is for supper? ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 8, $$Last year the fishermen fought with the surfers. Angry fists and shouting words. “Whaaat? Whaaat? Whaaat? ” cried the gulls. “There’s enough sea for everybody,” said Yusuf’s father. He showed them the fishing licence that had been Oupa Salie’s. “Waves for all. Water for free. ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 9, $$Ouma Safiya watches through her binoculars, her fingers curled in curiosity. The shark siren sounds. Swimmers run back to the sand and grab their towels. Surfers rush to the shore, carrying their boards under their arms. Under the showers they strip off their wetsuits. “Whaaat? Whaaat? Whaaat? ” cry the gulls. “What will Yusuf’s father bring from the ocean? ”$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 10, $$Yusuf’s father and uncle and cousins heave and pull. A little shark has been caught. It twists and thrashes in the waves. Yusuf’s father untangles the nets, singing to the shark: “Drop and swish. Find a fish. Pull and plop. Don’t you stop. ” When the shark at last is free it streaks back into the waves, leaving only one fat yellowtail in the net. Ouma Safiya will be pleased.$$),
    ('9c9e6754-fe46-11e5-86aa-5e5517507c66', 11, $$The men pull the boat in and coil up the cables. A hard white triangle catches Papa’s finger. “Whaaat? Whaaat? Whaaat? ” cry the gulls. “What did you bring back for Yusuf? ” As the sun goes down, Papa answers the gulls. “A lucky shark tooth for my boy. ” At home Yusuf holds his gift up to the stars.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 0, $$I was born in summer, in a town called Matatiele in the Eastern Cape. Matatiele is near Lesotho where there are many mountains. In the winter they are covered with snow.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 1, $$My father was a builder and he moved from place to place to find work. We moved to Lesotho and that’s where I started school. I was very happy. But when I was eleven years old, I grew tired and weak, and then I couldn’t walk. My parents took me to the hospital.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 2, $$I had to stay in hospital for three years. I was very tired and I slept many hours every day. After three years the doctors told me I would not be able to walk again. I was very sad because I love sports.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 3, $$I went to a special school in Umtata, and my teachers encouraged me. It was a very busy school, with lots of activities like sport and sewing. On weekends we had tasks to do. We had to clean our rooms, polish our shoes and clean our wheelchairs.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 4, $$I decided to keep trying, and never give up. If you have a disability, you can still do something you love. I love to see how far I can go, so I entered a competition. I won a bronze medal for shot putt, a silver medal for discus and a gold medal for javelin.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 5, $$I wanted to get better and better at my sports, so I trained very hard. When I rested, I loved to sew and listen to gospel music.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 6, $$I entered more competitions and I got many medals and prizes. I started to dream about maybe competing in the Paralympics one day.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 7, $$The Paralympics are just like the Olympics, where the best athletes in the world compete for gold, silver and bronze medals. But in the Paralympics, the athletes are disabled in different ways, so they have to try even harder to train and win!$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 8, $$Then I heard that I was going to Sydney in Australia, to take part in the 2000 Paralympics. At last we were in the plane, flying over the Indian Ocean!$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 9, $$But when I got there, I suddenly felt very scared of all the people watching me. I just wanted to go home again.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 10, $$Then, when I threw my javelin it landed far in front of everyone’s. I broke the world record and I got a gold medal! I was the first African woman to win a gold medal in the Paralympics. I was so happy and very proud.$$),
    ('9c9e6d12-fe46-11e5-86aa-5e5517507c66', 11, $$My motto is: Keep going, follow your dreams and never give up. Even if something happens to make you sad or scared. That is what I teach my little girl, Azamazi. She is eight years old and she also loves to do athletics and gymnastics. I am still training and going to competitions, and in 2016 I hope to go to the Paralympics in Rio de Janeiro.$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 0, $$On Sunday, Jimmy Zogba scored the winning goal.$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 1, $$On Monday, the Cool Cat Crew strutted by.$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 2, $$“Hey, Rafiki, where’s your zebra hair? Your hair’s so plain, like you don’t care. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 3, $$“Hey, Rafiki, where’s your fake tattoo? Your skin’s so boring. You are too. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 4, $$“Hey, Rafiki, where’s your bling? Your teeth are wonky, that’s the thing. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 5, $$That day, Rafiki walked home slowly.$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 6, $$“Auntie, can I have zebra hair? ” “I can’t cut you zebra hair. Actually, I wouldn’t dare. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 7, $$“My skin’s so boring, Sisi. Can you make a fake tattoo? ” “You don’t need one to look like you. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 8, $$“Mkhulu, I wish I had some bling. ”“Bling, my child, don’t mean a thing. ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 9, $$The next weekend, Santi Ramires scored the winning goal.$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 10, $$On Monday, the Cool Cat Crew strutted by. “Hey, Rafiki! Looking fine! ”$$),
    ('9c9e6e52-fe46-11e5-86aa-5e5517507c66', 11, $$Rafiki shrugged. “I look like me; this style is mine. ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 0, $$One day Tortoise was walking through the veld. He was searching and searching. He gazed into the distance and squinted at the grass. “Are you looking for something? ” Snail asked. “Yes, I’m looking for my house. Have you seen it? ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 1, $$“No, I haven’t, but I’ll help you look! ” She climbed onto Tortoise’s shell. Tortoise walked on with Snail on his back. They looked and looked, but there was no sign of a house.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 2, $$“Are you looking for something? ” asked Sparrow. “Yes, we’re looking for Tortoise’s house. Have you seen it? ” “No, I haven’t, but I’ll help you look! ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 3, $$Sparrow flapped his wings and he whizzed away. “You’re going too fast! ” called Tortoise. “Alright, then I’ll hop on too. ” Tortoise walked on with Snail and Sparrow perched on his shell. They looked and looked, but there was no sign of a house.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 4, $$“Are you looking for something? ” asked Ladybird. “Yes, we’re looking for Tortoise’s house. Have you seen it? ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 5, $$“No, I haven’t, but I’ll help you look! ” Ladybird hopped onto Tortoise’s shell. Tortoise walked on with Snail and Sparrow and Ladybird sitting on his back. They looked and looked, but there was no sign of a house. A breeze started to blow.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 6, $$“Are you looking for something? ” asked Mouse. “Yes, Mouse, I’m looking for my house. Have you seen it? ” “No, I haven’t, but I’ll help you look! ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 7, $$Mouse jumped onto Tortoise’s back. Tortoise walked on with Snail and Sparrow and Ladybird and Mouse on his back. They looked and looked, but there was no sign of a house. The wind swept the leaves off the ground and swirled them around Tortoise.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 8, $$The wind got stronger and stronger. The sky turned dark. “Oh, where is my house? ” Tortoise sighed. Thunder roared in the hills. Lightning flashed in the distance. Drip, drip came the rain. “Oh, where is Tortoise’s house? ” asked Snail and Sparrow and Ladybird and Mouse.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 9, $$The wind whirled and whipped and blew Snail and Sparrow and Ladybird and Mouse right off Tortoise’s back.$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 10, $$“Eek! ” squeaked Tortoise with a fright, and he shrank back into his shell. It was warm and cosy inside. “Oh, here is my house! ”$$),
    ('9c9e6f9c-fe46-11e5-86aa-5e5517507c66', 11, $$“Oh, here is Tortoise’s house! ”$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 0, $$Graça was about to be born in a small village in Mozambique. The country was poor and the people did not yet rule themselves. Children didn’t have good schools and many couldn’t read. Graça’s mother dreamed of giving her children better opportunities. But without education there was little hope.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 1, $$Baby Graça would be the sixth child. But with this joyous event there was great sadness. Their beloved father was dying. He dreamed that his youngest daughter would go to a good school. He knew that education would give her opportunities he never had. His family promised to make their dad’s dream come true.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 2, $$Just weeks after their dad died, the new baby was born. She was given a name to match the beauty and blessing that she was – Graça. As the years passed, Graça brought much joy to her family and they kept the promise made to their father. Graça would have a good education.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 3, $$Graça worked hard at school and as a teenager she received a gift that would change her life. It was a scholarship to attend a rich city school. She dreamed of becoming a teacher and using her education to educate others. She wanted the children of her beloved Mozambique to know reading and learning. She dreamed of a time when all children would go to school.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 4, $$Graça did her best in that city school and years later she was blessed again. It was another scholarship to attend a university in faraway Portugal. She met new friends, learned new languages and read a bounty of books. She realised her dream of becoming a teacher. All this made Graça very happy. There was only one thing that still made her sad…$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 5, $$Back at home people were still not free. But now Graça had an education, skills, and hope. She also had friends who felt as she did about children’s right to learn. She would use her knowledge and work with her friends. Together they would bring change to Mozambique.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 6, $$Finally with the help of all her friends, Mozambique was free!$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 7, $$The man chosen to lead the country was Graça’s special friend, Samora Machel. They fell in love and got married.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 8, $$Graça was given the important job of making sure that all children in Mozambique got a good education. It was a hard job because there were so many children in Mozambique who couldn’t read. She knew that they needed education and wanted to make real change in her country. She started with primary schools and getting boys and girls into classrooms. Literacy was her focus and putting books into children’s hands.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 9, $$Graça and Samora had two children. They shared a dream to create good lives for their own family and for the Mozambican people. They were happy and hopeful. Then one terrible day, Samora died in an aeroplane crash.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 10, $$Graça mourned Samora for many years, but she found love again. She met a man who had also spent his life dreaming of bringing freedom, hope and education to his people. Graça married Nelson Mandela and together they worked to help Africa’s children.$$),
    ('9c9e71cc-fe46-11e5-86aa-5e5517507c66', 11, $$Here’s a book, my child. What will it inspire you to do?$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 0, $$Mouse was looking for a new house.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 1, $$This looks like a nice house.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 2, $$“You can come and sleep with me,” said Puppy. “Thank you,” said Mouse.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 3, $$That night, Mouse’s dreams were bouncy and muddy.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 4, $$“You can come and sleep with me,” said Parrot. “Thank you,” said Mouse.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 5, $$That night, Mouse’s dreams were noisy and wild.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 6, $$“You can come and sleep with me,” said Fish. “Thank you,” said Mouse.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 7, $$That night, Mouse’s dreams were cold and wet.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 8, $$Mouse needed somewhere warm and dry.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 9, $$$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 10, $$Mouse found a bookshelf nearby.$$),
    ('9c9e72e4-fe46-11e5-86aa-5e5517507c66', 11, $$That night, Mouse had warm and cosy dreams.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 0, $$The Winter cold had passed. Spring was coming to Nkanyezi’s village. Soon the villagers would gather to celebrate the new season. Nkanyezi looked forward to the Spring festival more than any other day in the year.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 1, $$One warm morning, Nkanyezi overheard two village elders talking about the festival. “The people of Ndlovu have lost their spirit of celebration,” one sighed. “How can we have a Spring festival in a village that has forgotten how to celebrate? ” asked another.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 2, $$Nkanyezi was worried. “How will the sun shine again unless we sing to wake it from its winter slumber? ” she asked herself. Nkanyezi thought for a long time. “I must find what we have lost,” she decided. “I must go in search of things that will bring backthe spirit of celebration to my village. ”$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 3, $$The elders gave Nkanyezi their blessing for the journey. They gave her a bag to carry the things she would find. Nkanyezi was afraid, but she believed she would succeed.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 4, $$Nkanyezi walked all day. She hiked up a hill, and down into a valley. She sailed across the great river, and climbed between sharp rocks. She marched across the plains until she reached the shadow of the red mountains.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 5, $$As night was closing in, Nkanyezi arrived at a village of patterns and colours as she had never seen before. She told the village elders about her journey to bring back the spirit of celebration to her people The mother of this tribe gave Nkanyezi a gift. She told the girl, “With love we give to you this paint to restore colour to a village that has gone dull. ” Nkanyezi thanked the elders and put the paint in her bag. Early the next morning she went on her way again, excited with this gift of colour.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 6, $$Nkanyezi walked all day, through a vast forest of giant trees. As the sky became too dark for her to see, she heard the sound of beating drums. She hurried towards the drumming, feeling the spirit of dance coming to her tired feet.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 7, $$Nkanyezi found herself in the village of the Bhubezi. People were sitting around a fire, drumming and singing. She had never before heard such wonderful music. She told the village elders about her journey to bring back the spirit of celebration to her people. The Bhubezi invited her to rest and stay the night.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 8, $$In the morning the chief called on Nkanyezi. “My child,” he said, “here is a special drum. It plays a new song every time you beat it. ” Nkanyezi thanked the elders and put the drum in her bag. She went on her way again, delighted with this gift of music and dance.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 9, $$On the third day of her journey, as she a passed a field of fat cows, her nose started to tingle. An aroma tickled her taste buds and her mouth started to water. She followed the scent, and arrived in a village to find people standing over steaming pots of stew. This tribe was famous for its feasts and Nkanyezi had never before tasted such flavours. After she had eaten her fill, she told the village elders about her journey to bring back the spirit of celebration to her people.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 10, $$The next day, the council of cooks gave her a secret spice blend. “Our daughter,” they said, “with these spices, happy tummies are guaranteed! We give you the gift of good food. ” Nkanyezi thanked the elders and put the spices in her bag. She knew she had everything she needed. With new energy she started the long journey back to the village of Ndlovu.$$),
    ('9c9e76ea-fe46-11e5-86aa-5e5517507c66', 11, $$When she arrived home the villagers gathered around her to hear of her adventures. She told them the tales of what she had seen, heard, and eaten. Then she opened her bag to share the gifts given. The people rejoiced to receive these treasures. Through the generosity of others and the courage of Nkanyezi, the villagers again found the colour, song and dance in their lives. And so the spirit of celebration was restored to the village of Ndlovu.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 0, $$Come back, cat! Play with me.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 1, $$Sit in your basket. Stay right here!$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 2, $$Come back, cat! That’s way too high.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 3, $$Come back, cat! Don’t go outside.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 4, $$Cat runs outside and chases butterflies.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 5, $$Come back, cat! That’s not yours.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 6, $$Come back, cat! What have you got?$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 7, $$Come back, cat. That’s not your friend!$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 8, $$Hello, cat! Are you back?$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 9, $$Stay in your basket. It’s nap time now.$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 10, $$Cat?$$),
    ('9c9e7820-fe46-11e5-86aa-5e5517507c66', 11, $$Cat sleeps peacefully on the couch with the feathers, thread and snail.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 0, $$In a village on the slopes of Mount Kenya in East Africa, a little girl worked in the fields with her mother. Her name was Wangari.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 1, $$Wangari loved being outside. In her family’s food garden she broke up the soil with her machete. She pressed tiny seeds into the warm earth.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 2, $$Her favourite time of day was just after sunset. When it got too dark to see the plants, Wangari knew it was time to go home. She would follow the narrow paths through the fields, crossing rivers as she went.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 3, $$Wangari was a clever child and couldn’t wait to go to school. But her mother and father wanted her to stay and help them at home. When she was seven years old, her big brother persuaded her parents to let her go to school.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 4, $$She liked to learn! Wangari learnt more and more with every book she read. She did so well at school that she was invited to study in the United States of America. Wangari was excited! She wanted to know more about the world.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 5, $$At the American university Wangari learnt many new things. She studied plants and how they grow. And she remembered how she grew: playing games with her brothers in the shade of the trees in the beautiful Kenyan forests.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 6, $$The more she learnt, the more she realised that she loved the people of Kenya. She wanted them to be happy and free. The more she learnt, the more she remembered her African home.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 7, $$When she had finished her studies, she returned to Kenya. But her country had changed. Huge farms stretched across the land. Women had no wood to make cooking fires. The people were poor and the children were hungry.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 8, $$Wangari knew what to do. She taught the women how to plant trees from seeds. The women sold the trees and used the money to look after their families. The women were very happy. Wangari had helped them to feel powerful and strong.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 9, $$As time passed, the new trees grew into forests, and the rivers started flowing again. Wangari’s message spread across Africa. Today, millions of trees have grown from Wangari’s seeds.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 10, $$Wangari had worked hard. People all over the world took notice, and gave her a famous prize. It is called the Nobel Peace Prize, and she was the first African woman ever to receive it.$$),
    ('9c9e7a6e-fe46-11e5-86aa-5e5517507c66', 11, $$Wangari died in 2011, but we can think of her every time we see a beautiful tree.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 0, $$Once upon a time on a little farm near a little village there lived a little chicken called Daisy.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 1, $$“When I grow up, I want to fly high, high into the sky,” Daisy said. But all the other chickens laughed at her.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 2, $$“You are so weird,” they said. “We won’t play with you anymore. ” “Daisy, we can all flap our wings but it’s very difficult for chickens to fly,” Mama told her.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 3, $$Daisy wouldn’t give up. Every day she practised by herself, flapping her wings. Flap, flap, flap, she would flap her wings but she couldn’t lift off the ground.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 4, $$While she practised, she imagined herself flying high into the sky and looking at the chickens below. She imagined herself flying past the sparrows and past the swallows. “Wow! ” the birds would say. “A chicken that can fly! ”$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 5, $$So … Flap, flap, flap, every day Daisy would flap her wings. She would lift off the ground but fall down again.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 6, $$“I’m never going to fly! ” Daisy cried to Mama. “The others are right. ” “Daisy, you are different from the other chickens. They don’t want to fly but you do! You can do it,” Mama said.$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 7, $$The following day Daisy climbed to the top of the chicken coop and flap, flap, flap, she flapped her wings. She flew into the air and flapped her wings … and flapped her wings … and flapped her wings and …$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 8, $$BAM! The other chickens laughed out loud. “Ha ha ha! We told you! Chickens can’t fly! ”$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 9, $$But the next day Daisy climbed even higher, right up to the top of the rondavel. Flap, flap, flap, Daisy flapped her wings. She flew into the air and flapped her wings … and flapped her wings … and flapped her wings and …$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 10, $$She kept flying! The wind beneath her wings grew stronger and she flew higher and higher! The sparrows and the swallows said, “Amazing! A flying chicken! ”$$),
    ('9c9e7b9a-fe46-11e5-86aa-5e5517507c66', 11, $$And the other chickens wanted to be just like her. They said, “Oh Daisy, you’re amazing! ”$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 0, $$One day, Mr Sloth came to visit. He said: I’m sleepy! I need a good branch for a bed!$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 1, $$I’m quite good at climbing. I know how to swing. But sleeping’s my favourite, favourite thing!$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 2, $$This branch looks lovely! I think I’ll sleep here. And you? Don’t you think that’s a splendid idea?$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 3, $$Oh no, Mr Sloth! A giraffe’s eating there! He might think you’re lunch and start nibbling your hair!$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 4, $$This branch looks lovely! I think I’ll sleep here. And you? Don’t you think that’s a splendid idea?$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 5, $$Oh no, Mr Sloth! There’s a beehive right there! You’ll never get sleep with those bees everywhere!$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 6, $$This branch looks lovely! I think I’ll sleep here. And you? Don’t you think that’s a splendid idea?$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 7, $$Oh no, Mr Sloth, that’s a snake over there! Not a branch! Poor old snake. You gave him quite a scare.$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 8, $$This branch looks lovely! I think I’ll sleep here. And you? Don’t you think that’s a splendid idea?$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 9, $$Oh no, Mr Sloth! There’s a bird squawking there! You’ll never get sleep with that noise in the air!$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 10, $$Try climb one more branch, Mr Sloth! they all said. And that branch was just the right one for his bed.$$),
    ('9c9e7cb2-fe46-11e5-86aa-5e5517507c66', 11, $$The bird and the snake, the giraffe and each bee were happy to have Mr Sloth in their tree.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 0, $$My name is Maddy Moona, and today I’m turning five. Dad promised I could choose a pet, a real one! Something live! We’ll travel across the whole wide world, searching Mali through Tibet, until we find the perfect one… Oh, I know just what I’ll get!$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 1, $$I’m going to get an elephant. I’ll ride on it to school. My brother Billy can walk behind, he’ll think I’m awfully cool. But… what if Ellie caught a cold? I guess she’d sneeze…. A LOT! There is no tissue big enough to wipe up all that snot.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 2, $$I want a Nile crocodile sent to me by the pharaohs. I’ll call him Tut and feed him soup, fish fingers, and baby marrows. I’ll keep him in the bathtub and brush his pearly whites, But… what if flossing all those teeth takes me all day and night?$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 3, $$Perhaps a pair of porcupines, for games of robbers and cops. Their prickly quills will be handy for holding up sweetie shops. I can munch away on candy bars while my gang sharpen their spines. But… what if my sharp-shooting pals put me in the firing line?$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 4, $$Maybe I need a stealthier plan. Let’s clear out the store with funk! There isn’t a smellier critter on earth. That’s what I want — a skunk! But… what if I can’t go into the shop after Skunky has let off his stink? Sweets are no good for my teeth anyway. A rotten idea! I need to rethink!$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 5, $$A rhino! The horns, the big stomping feet, the armour on both of its flanks! Billy would never chase me again. It would be my own personal tank. But… what if Billy raises his temper and Rhino goes on the rampage? Crash bang boom! The teacups! The plates! Now I’m grounded ‘til I’m gran’s age.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 6, $$I need a beast to tame my brother. With teeth, sharp claws and a roar. A LION! I could feed it Billy biltong… Yes! A lion would settle the score. But… a lion has a huge appetite. Skinny Billy won’t satisfy. And once Brutus has a taste for us Moonas, he’ll see me as Maddy stir-fry.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 7, $$Dad thinks I should choose a cuddlier pet. My parents are so hard to please. They want me to have a pet I can hug. A python? A python has squeeze. But… if Snakey develops too much of a crush, he’ll suffocate me with affection. To be honest, I just can’t marry a snake! And reptiles can’t handle rejection.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 8, $$No, reptiles aren’t the way to go. I definitely need something taller. A giraffe would be awesome. I’ll slide down her neck, and think up a long name to call her. But… something more than eight foot tall is no good. Our house has a rather low ceiling. I’d spend hours massaging cricks out her neck. My fingers would lose all their feeling.$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 9, $$None of these are the perfect pet! Oh what, oh what will I get?$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 10, $$Those animals just don’t work. None are my perfect partner in crime. I want something with fur, a pet who will follow. Oh wait! I know — a canine!$$),
    ('9c9e7dca-fe46-11e5-86aa-5e5517507c66', 11, $$My Bandit is the biggest bark on the block! He’s the fastest pup in the west! Nothing can stop us. Not Billy nor bedtime. I love my Bandit. He’s my best!$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 0, $$Who are you?$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 1, $$Is that goo? Eeuw! I want some too.$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 2, $$We are two. How old are you? Six hundred and thirty two?$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 3, $$I like blue. Do you too? I choose two shoes. Which do you choose?$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 4, $$Horseshoes!?$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 5, $$I make toys with boys.$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 6, $$We make lots of noise. Whaaa! eurgghhh…aargh!$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 7, $$I take a nap on Gogo’s back.$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 8, $$I don’t nap!$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 9, $$I stay upright all through the night.$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 10, $$The ball goes THWOCK! Buddy, you ROCK!$$),
    ('9c9e819e-fe46-11e5-86aa-5e5517507c66', 11, $$That’s what we do. How about you?$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 0, $$One night Grandpa was tucking me in. His hands were soft and his hair was thin.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 1, $$‘I’m going to tell you a special story, about a girl named Lory Dory. ’$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 2, $$You couldn’t see Lory Dory at all because she was born invisible.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 3, $$You’d only see Lory when rain hit her head, or when she was curled under blankets in bed.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 4, $$Lory was left out of all the kids’ games. They teased her and they called her names. ‘Look, it’s Lory. The Imaginary Friend! She’s not like us, she’s just pretend! ’$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 5, $$One day at school, a boy wanted to know: ‘How do you look? I only see you in snow. ’$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 6, $$‘Can you paint yourself? ’ Lory knew that she could. But not in the same way the boy thought she would.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 7, $$Lory painted her body with all that she loved from the world all around and the sky up above.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 8, $$She painted herself every day with such pride, to bring out the person who she was inside.$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 9, $$I know I’m invisible and hard to see. So I painted these pictures to show the real me. ’$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 10, $$‘Are you making this up, Gramps? Is this story true? ’ ‘Lory is real – real as me, real as you. ’$$),
    ('9c9e83b0-fe46-11e5-86aa-5e5517507c66', 11, $$When Grandpa had left me, I can’t quite be sure, but I think I saw Lory just outside my door.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 0, $$Once upon a time, not so far away, a baby called Phyllis was born for ballet. Two people in love, her Mom and her Dad, could not have known yet what a dancer they had.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 1, $$When Phyllis was four she had us transfixed: impressing her teachers with ducky feet flicks. Before school and after, she danced every day. Nothing pleased Phyllis more than ballet.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 2, $$The world would soon see, when, only fifteen, she travelled to London to live out her dream. Far from home and her friends, she was starting afresh. The Royal Ballet school would soon be impressed!$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 3, $$When she danced Swan Lake it was fit for the Queen! After years pirouetting, it was time to be seen! She took to the stage, leaping, twirling about, with everyone smiling! They clap and they shout!$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 4, $$From Mexico to Canada, the US to France, everyone asked her to visit and dance. With the Royal Ballet, and all of her friends, she spread love for dancing so it never would end.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 5, $$Still, Phyllis missed home, they’d been too long apart. She longed to return and to make a fresh start. So she leaped and she bounded to her beautiful land, to walk once again on South African sand.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 6, $$Dance isn’t just fun, as Phyllis well knew: she worked day and night, and with hard work she grew. Always smiling and tireless, through good times and tough,she aimed for her best. ‘Good’ was never enough.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 7, $$Romeo and Juliet, Swan Lake and Giselle. She captured each audience under her spell. With Gary Burne beside her, Eduard Greyling too, her dancing was magic in every review.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 8, $$Reward comes eventually, when you’re put to the test. And one day South Africa would call her the best: ‘Prima Ballerina Assoluta’, greatest dancer of all, her title forever. Phyllis wanted no more.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 9, $$Soon Phyllis found love when she met Philip Boyd, a dancer himself! They were both overjoyed. In love, they soon married, and together they’d dance. No match could be better when given the chance!$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 10, $$They didn’t have children but never were sad, for they had a way to help all moms and dads. Their school, Dance For All, would give children a chance, from all walks of life, to learn and love dance.$$),
    ('9c9e8586-fe46-11e5-86aa-5e5517507c66', 11, $$Her gift to the world and all her success help others to realise they can be their best. They dance for us now, inspired by her feats,inspiring us, too, as we dream in our seats.$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 0, $$Bathtime is Jack’s favourite part of the day. ‘I’ll be back in a few moments,’ says his mom. ‘Make sure to clean behind your ears. ’$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 1, $$There’s a SWOOSH. And a swish of a tail. And then…$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 2, $$Jack’s bathtub safari begins!$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 3, $$Look at what’s coming! There’s a twist and a turn.. Something’s growing… It’s a…$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 4, $$TOOOT!$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 5, $$There’s a RUMBLE! UP UP It’s going up and…$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 6, $$SPLASH!$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 7, $$There’s a SPLOSH. Something bubbles. It’s time to…$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 8, $$AAAAAAH But something’s lurking in the background…$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 9, $$ROAR$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 10, $$‘Time to get out. I hope you’re clean and ready for bed. ’$$),
    ('9c9e86da-fe46-11e5-86aa-5e5517507c66', 11, $$Jack is fast asleep in bed surrounded by his toy animals.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 0, $$It had been raining for days, and everyone was grumpy. Everyone except Sizwe, who woke up with a smile every morning. “Yoh! Sizwe! That smile is magic! ” said Gogo. “Is it for me? ” Sizwe clapped his hand over his mouth. “But it’s MY smile, Gogo,” he whispered.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 1, $$His mother laughed. “Sizwe! A smile is something you can give away without losing it. Look! ” She lifted him up to the mirror. There was his smile, just as bright as before.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 2, $$It was time to go out. Mama buttoned up Sizwe’s raincoat, and off they went, through the rain, to the library. Down the street, Sizwe’s best friend Zanele stood at the window of her house, looking sadly at the rain. Sizwe felt his smile creeping, creeping up. Before he knew it, his smile LEAPT out, and flew across the garden to Zanele.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 3, $$Zanele held on tightly to the smile – it was far too precious to let it get away. As Sizwe walked away to the library, Zanele’s doorbell rang. It was the postman, with a letter from her favourite cousin. Zanele was so happy, that the smile bounced up, and beamed out at the postman. “Thank you, Mister Postman! ” she said.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 4, $$Zanele’s smile was the brightest thing the postman had seen all morning. It kept him warm as he trudged off through the rain. He came to a big house. Inside the gate, a dog was spinning around in circles, barking, barking, barking. He was so silly, that the postman couldn’t help smiling. The smile bounced through the gate with a glitter of glee.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 5, $$The dog stopped barking. He pricked up his ears and wagged his tail. Then he turned and ran back to the house with the precious, warm smile. A bent old man opened the door. “Oh, no! You can’t come inside. You’re all wet! ” he told the dog. But right away, the smile beamed up at the old man.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 6, $$The old man stood a little straighter. “Eish,” he said, “Who cares if it’s raining? Let’s go for a walk, boy! ” And off they went, splashing in the puddles. There, at the zebra crossing, stood grumpy Mrs Makabela, the traffic cop. She looked cold, and wet, and miserable. The old man knew just what to do. “Morning, Mrs Makabela! ” he called, and smiled his biggest, brightest smile. But Mrs Makabela… did not smile back.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 7, $$Standing in the rain for days can make a face sad, sad, sad. But a smile is a magical thing and, by now, the smile was so strong, and so bright, that it was very hard to keep inside. It didn’t work right away, but bit by tiny bit, it began to creep out until, at last…! A great, big smile lit up Mrs Makabela’s face! The school bell rang, and children ran to cross the road. Mrs Makabela put up her sign, and smiled, and smiled, at each and every child.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 8, $$The children smiled at their moms and dads, and their gogos and tatas and brothers and sisters. They smiled at the bus driver and the greengrocer, and Mme Makau, who went off to smile at her husband, who smiled at the mayor… The smiles leapt and rolled and beamed and gleamed until EVERYONE was smiling and giggling and laughing out loud in the rain.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 9, $$In the library, everything was quiet except for the sound of the rain. “It’s time to go,” said Sizwe’s mother, closingher book. “Aw, mom! ” said Sizwe, who had run out of smiles.$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 10, $$But as they stepped out into the street… WHAT A SIGHT! Everyone in town was there! Everyone! And they were ALL smiling!$$),
    ('9c9e87f2-fe46-11e5-86aa-5e5517507c66', 11, $$The smiles bounced around and beamed at Sizwe. They warmed him, and tickled him, and crept up, up, up from his toes… to the TOP of his head. He was so full of happiness that the smile burst out, brilliant and beaming bright. And something changed. The dark, gloomy, rainy afternoon didn’t seem so dark anymore. Could it be…? YES! The clouds parted, and the warm sun shone down on them, with the biggest, brightest, most brilliant smile of all.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 0, $$I wonder if there’s another me somewhere in the world.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 1, $$Who looks the same. And talks the same.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 2, $$And even has my curls.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 3, $$Someone with my eyes my ears. Who even has my laugh.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 4, $$Who can do what I can do …$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 5, $$… and can’t do what I can’t.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 6, $$I’ve looked and looked everywhere to find another me. I went down to the park and looked behind the trees.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 7, $$I looked around, up and down …$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 8, $$… at every single face.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 9, $$I couldn’t find another me in any single place.$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 10, $$There’s only one me in the world! I’m special, oh it’s true!$$),
    ('9c9e8c0c-fe46-11e5-86aa-5e5517507c66', 11, $$But not just me, don’t you see? There’s only one of you!$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 0, $$When we go walking and the road is long, we’ll walk together singing a song.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 1, $$I am with you and you are with me. A journey is fun with our family.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 2, $$I’ll keep you cosy like a mother hen. She keeps her chicks warm under her wing.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 3, $$If the rain starts to fall down from the sky, like that good hat I’ll keep your face dry.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 4, $$If storm clouds get angry and grumble and moan, be brave, why cry? You’re not alone.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 5, $$We’re walking together so we never get bored. Look up! Look around! See where we’ve explored!$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 6, $$If you see something that’s funny to see, I don’t want to miss it. Please share it with me!$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 7, $$If your feet start to hurt from the distance we’ve passed, don’t worry, we’ve made it! Here’s the clinic at last.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 8, $$We all need to check our throat, lungs and ears. Get strong as you grow, it’s no reason for tears.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 9, $$Do you think it’s scary? Here, hold my hand. She’ll check your blood pressure with this clever armband.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 10, $$They give us our medicine, tell us what we should know, to keep us all healthy. Now back home we go.$$),
    ('9c9e9102-fe46-11e5-86aa-5e5517507c66', 11, $$It’s okay to be tired, there’s so much we’ve seen. Now it’s your bedtime. Sleep well and sweet dreams.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 0, $$“Ouch! ” Mama Heron hurts her wing and leg on barbed wire.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 1, $$“I am hurt. I can’t get home to my children. ” “Please help me. ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 2, $$“Why are you crying Mama Heron? ” “I can’t get home to my children. ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 3, $$“I will help you,” says Lungile.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 4, $$“Thank you, Lungile! ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 5, $$The next day, Gogo sends Lungile to the shop to buy bread. On the way, he stops to play with his friends in the river.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 6, $$Eish! The money is gone.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 7, $$“Don’t come home until you find that money! ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 8, $$“Why are you crying, Lungile? ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 9, $$“I lost the money Gogo gave me to buy bread. We have no supper now. ” “I will help you. ”$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 10, $$Mama Heron’s sharp eyes see the coins shining in the water.$$),
    ('9c9e9396-fe46-11e5-86aa-5e5517507c66', 11, $$“Thank you, Mama Heron. ”$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 0, $$“What a beautiful day,” says Mom. “Wake up Nicholas. ” “Hello sun,” says Nicholas. “Good morning birds. ”$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 1, $$“It’s a lovely day,” says Dad. “Let’s have a picnic by the river. ” “Can my friend Jacob come? ” asks Nicholas.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 2, $$“Don’t forget me. I love picnics! ” says Donkey. “And me. I want to come too! ” says Dog. “Follow us,” say the birds.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 3, $$Dad carries a picnic basket on his head. Mom, the children and all the animals follow him to the picnic spot.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 4, $$“I’ll race you to that tree,” Nicholas says.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 5, $$“I won, I won,” says Donkey. “Not fair,” says Nicholas. “You’ve got four legs. ”$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 6, $$“Look what I can do,” says Nicholas. “I bet you can’t do this,” says Jacob.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 7, $$“Here’s our picnic spot,” says Dad.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 8, $$“Race you to the water! ” says Jacob.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 9, $$“Come and eat, boys and girls,” says Mom.$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 10, $$“Time to go home,” says Mom. “Say goodbye to Jacob. ”$$),
    ('9c9e94e0-fe46-11e5-86aa-5e5517507c66', 11, $$Nicholas and Dog are fast asleep in bed, while Donkey sleeps outside under the stars.$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 0, $$Londi was a dreaming girl. Up in the sky, she didn’t see clouds.$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 1, $$Instead Londi saw flying geese, jumping fish, and fluffy sheep running home.$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 2, $$One afternoon, Gogo came outside, looking tired. “Londi, stop dreaming! ” she said. “It’s time to go and fetch the water. ”$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 3, $$Londi stood up and smiled at her feet. “Let’s go, feet! You know the way there! ”$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 4, $$Londi started walking to the tap. She hopped over the rocks. She crept past Mama Neli’s house. She dashed down the path.$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 5, $$The line at the tap was long. “Oh no! ” Londi said to her feet. “We’ll have to wait. Let’s stay in line. No dreaming away! ”$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 6, $$Ooh! Londi thought. But what’s that shining over there? I wonder who lost their shoe?$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 7, $$Did it belong to a girl like me? Or something else…$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 8, $$And what’s that under there? Cheep! Cheep!$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 9, $$And what’s that big shadow? Uh oh, it’s Gogo! “Londi, your bucket nearly rolled away! ” “Sorry, Gogo. I dreamed too far, again. ”$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 10, $$They filled up the bucket together. Londi watched the big sun sink into the hills. “Come let’s go, my dreaming girl,” said Gogo.$$),
    ('9c9e96ac-fe46-11e5-86aa-5e5517507c66', 11, $$“Look, Gogo! There’s a pink pig in the sky! ” “Oh Londi… It’s just a cloud,” Gogo sighed. Londi took Gogo’s hand and they walked home together happily.$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 0, $$My sister Kifue chases roosters that crow. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 1, $$My brother Katleho has a ball to throw. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 2, $$My cousin Kutloano plants seeds in a row. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 3, $$My cousin Kamohelo leans on her hoe. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 4, $$My aunt Keromang has a dress to sew. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 5, $$My uncle Khotso herds the cattle that low. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 6, $$Mama dries wheat when the wind does not blow. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 7, $$Papa rides a horse over mountains in snow. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 8, $$Grandpa’s slow donkey walks to and fro. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 9, $$Grandma sings songs till the fire burns low. What do I do? What do I know?$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 10, $$You know how to say yes. You know how to say no. That’s what you do! That’s what you know!$$),
    ('9c9e9e5e-fe46-11e5-86aa-5e5517507c66', 11, $$Everyone laughs when you put on a show. Your work is to play. Your work is to grow.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 0, $$These are my big brother Sbu’s shoes.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 1, $$Look what I can do in them.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 2, $$I can race cars!$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 3, $$Sometimes, I even race our bouncy dog.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 4, $$With Sbu’s shoes I win every time.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 5, $$Wait! Let me show you one more thing.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 6, $$Watch me dance and spin.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 7, $$I can cartwheel over and over.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 8, $$I’m a monkey! Look at me hang upside down.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 9, $$Watch me jump and catch the moon.$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 10, $$Here, try them on!$$),
    ('9c9e9fc6-fe46-11e5-86aa-5e5517507c66', 11, $$See what you can do in Sbu’s special shoes.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 0, $$Sindi was a very lively little girl who loved to sing and dance. She lived on a farm with her parents and her Gogo. Sindi enjoyed following Gogo around and feeding the animals.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 1, $$One evening while Sindi and her family were having dinner, Sindi’s mother had something to tell her. “Sindi,” she said, “after the long Christmas holidays, you are going to go to school. ”Sindi was so excited. She was happy that she would finally get to learn how to read and write.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 2, $$When Sindi was happy, she danced. Her joy spread to the farm animals. The dogs barked more loudly. The cows mooed more beautifully. The butterflies flapped their wings and landed in her hair.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 3, $$When Sindi danced, she swayed from left to right, as if she were pushed and pulled by the wind. She sang along with its soft, slow music.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 4, $$As the holidays were ending after Christmas, Sindi started to wonder what school would really be like. She did not want her mother to know that she was nervous, so she asked Gogo what school would be like. “School is very serious,” Gogo said. “There is no more time for song and dance, only learning. ” This did not make Sindi happy at all.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 5, $$The night before school started was very hot. Sindi just could not sleep! She tiptoed outside and sat on the stoep, looking up at the dark sky. The moon was big and bright and beautiful and the stars were twinkling.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 6, $$Sindi spoke to the beautiful moon. “Dear moon so bright,” she said, “are you afraid of the dark? Is that why you ask the stars to keep you company? ” “I am going to school tomorrow, what will it be like? ” “Will they let me sing? Will they let me dance? ”$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 7, $$Sindi started to sing. What she saw next made her rub her eyes in disbelief. Was she dreaming? The moon was smiling! And the stars were dancing to her song!$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 8, $$A gentle voice spoke to her. “Dear little Sindi,” the voice said. “School is a wonderful place. You will learn many things: to read and write, to sing and dance and to make many friends. ”“But for now, Sindi, you must rest. Tomorrow will be beautiful. ”$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 9, $$Sindi had never seen anything this amazing. She wanted to wake everyone up and show them the talking moon and dancing stars. But the moon stopped her. “Shhhh, Sindi,”it said. “This is our little secret. ” The moon winked. Sindi returned to bed, comforted by the moon’s wise words, and slept peacefully.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 10, $$The time came for school. Mama held Sindi’s hand as they approached the school. She was confident that the day would be beautiful, because the moon had told her so. Children were arriving with their mothers and fathers. They all looked excited. Sindi could not wait to make friends.$$),
    ('9c9ea21e-fe46-11e5-86aa-5e5517507c66', 11, $$By lunch time, Sindi loved everything about school. “I wish the moon could see me now,” she said to herself. “Now I will learn to read. I will learn to write. But also I will sing and dance! ” And all of Sindi’s new friends danced with her, just like the animals had done. They clapped their hands and sang to her tune.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 0, $$Nestled in the Kingdom of the Zulu is a magnificent place called the Valley.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 1, $$A little girl called Jabulile lives here. Jabulile was always a happy child. She was also curious, and full of questions about life. Everything fascinated her.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 2, $$Jabulile’s father was a mielie farmer. Her mother was a teacher. They taught her to dream big dreams. Jabulile’s biggest dream was to help people.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 3, $$Everyone in the village was Jabulile’s friend, especially the elders. They taught her about the wise men and women who once lived in the Valley. Jabulile also wanted to be wise.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 4, $$One awful day, the clouds began to gather over the Valley. Everything grew dark and grey. An ugly storm swept over the land.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 5, $$Great gusts of wind blew the roofs off the huts. All the animals lost their homes. It was a very sad day.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 6, $$The village folk cried, “What shall we do now? ” “All the crops are ruined! ” cried the farmers. “Our homes are gone! ” said the elders. All hope seemed lost. But Jabulile remembered something her wise father once told her.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 7, $$Jabulile started speaking to the villagers. “The storm only hurts us,” she said, “because of the way we choose to see it. If you look up the sun is shining again. It is a new day. “After every storm, there must be a rainbow! ” she shouted excitedly.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 8, $$Just then a glorious rainbow appeared in the sky.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 9, $$The villagers saw the rainbow and they began to smile. It stood as a promise that the storm was over.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 10, $$The villagers rebuilt their homes. Farmers planted new crops. The grass grew greener than ever before.$$),
    ('9c9ea48a-fe46-11e5-86aa-5e5517507c66', 11, $$Once again there was hope and happiness in the Valley.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 0, $$Simamkele loves dolls. Mama buys him lots. They keep his loneliness away. Sima’s favourite doll is Siza. Sima wants to be a nurse when he grows up.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 1, $$He loves to put on Mama’s skirt, and twirl. Like magic, he suddenly becomes Sima the nurse. He plays hospital-hospital and makes sickly Siza and all his dolls better.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 2, $$Wherever Sima is, Siza is there too.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 3, $$But Sima’s friends do not like Siza. One day, they took him away and stuck his head in the toilet.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 4, $$When Papa came home, Sima was nursing Siza. ‘What are you doing? ’ asked Papa. ‘I’m being a nurse,’ said Sima. ‘Will you play with me? ’ ‘Yes. But we will go to the park and play soccer,’ said Papa.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 5, $$His friends saw Sima and Papa playing soccer. They joined in. Sima and Papa often play soccer now. But they still haven’t played with dolls.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 6, $$One day, Sima was playing hospital-hospital with his dolls. He heard Mama shout. ‘Sima! Run! Papa is waiting to play with you at the park. ’$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 7, $$‘Why on earth are you wearing a dress? ’ said Papa in an angry voice. Just then a ball flew out of nowhere and …$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 8, $$… knocked Papa down. Everyone panicked. Except Sima. He knelt and tied his blanket around Papa’s bleeding head. ‘Call an ambulance! ’ he shouted.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 9, $$‘He needs stitches in his head. You did just the right thing,’ said the nurse. Sima was proud.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 10, $$‘You’re a hero. You’ll make a great doctor one day. ’ ‘But I want to be a nurse, just like you,’ said Sima.$$),
    ('9c9ea96c-fe46-11e5-86aa-5e5517507c66', 11, $$‘Thank you, Nurse Sima,’ said Papa. Now Sima and Papa play hospital-hospital and soccer – and his friends do too.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 0, $$Tinny Tim was sitting on the road when a button bounced his way.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 1, $$“I wonder where this comes from,” he said. He wanted to find out.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 2, $$It was busy on the side of the road. “Woah! ” He nearly got squashed.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 3, $$He made a lucky escape. “It’s scary out here,” he said.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 4, $$“Hey there, is this yours? ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 5, $$The green man said nothing. He just turned red. “What a rude person. ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 6, $$Tinny Tim carried on looking. “Whose button is this? ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 7, $$“Woah..! …at least he’s friendly. ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 8, $$“I’ve got to get to the other side. I’m sure that’s where this comes from. ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 9, $$SPLASH! “That was close. ” He waited for the cars to pass before he carried on.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 10, $$Maybe this was who he was looking for. “Hello, who are you? ”$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 11, $$“I’m Ruby Rags. ” “I think this is yours,”he said.$$),
    ('9c9eb2cc-fe46-11e5-86aa-5e5517507c66', 12, $$“Thank you, little robot. Can we be friends? ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 0, $$It is one week until Thato’s birthday. That’s seven whole days!$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 1, $$His mama says: “Your birthday present will be a BIG surprise! ” Thato wonders: what will it be?$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 2, $$On Monday Thato thinks: Maybe I will get giant wings so I can fly high in the sky like a bird…”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 3, $$On Tuesday Thato thinks: “Maybe I will have a birthday cake as big as a house! ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 4, $$On Wednesday Thato thinks: “Maybe I will get a rocket ship to whizz up to the moon.$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 5, $$On Thursday Thato thinks: “Maybe I will get fins so I can swim under the water like a fish. ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 6, $$On Friday Thato thinks: “Maybe I will get magic soccer boots and score a thousand goals! ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 7, $$On Saturday Thato thinks: “Maybe I will get a key that opens a box filled with treasure! ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 8, $$On Sunday it is Thato’s birthday. Mama smiles and says: “Come and see your surprise! ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 9, $$It is the best present ever. Thato’s big brother Kudzai has come to visit all the way from the big city!$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 10, $$Thato smiles and smiles and his big brother lifts him up in the air and hugs him. Kudzai asks:“What do you want to do for your birthday, little brother? ”$$),
    ('9c9eb68c-fe46-11e5-86aa-5e5517507c66', 11, $$And Thato knows exactly what they will do the whole day long.$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 0, $$Nandi sat on the blue steps of her house.$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 1, $$She was wondering…$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 2, $$What if jelly beans made you jump really high? You could get to school in one big leap!$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 3, $$What if goats and chickens could talk? Would they tell good jokes?$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 4, $$What if houses were rocket ships? Your family could go on holidays to the moon!$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 5, $$What if no one had to cook? What if supper just arrived on the table? (And it was always your favourite.)$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 6, $$What if ice-lollies never melted? They could last all summer.$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 7, $$What if the pictures in books flew around your head when Dad read to you?$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 8, $$What if my pink gumboots were magical? I could run faster than my big brother!$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 9, $$What if you squeezed your eyes shut and…$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 10, $$“Nandi, what are you doing? ” asked Nandi’s big brother. Nandi sat back on the step with a big smile on her face.$$),
    ('9c9f3292-fe46-11e5-86aa-5e5517507c66', 11, $$“Just wondering,” she said.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 0, $$Lara the ladybird was a special bug. Unlike all her friends, she had bright yellow wings.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 1, $$Everyone loved her yellow wings. Each morning, Bibi Butterfly said hello. And Manto Mantis always waved.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 2, $$Even Sesa, the sulky spider, was happy to see her. At school, she played with lots of friends.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 3, $$But Lara wanted to be like the other ladybirds. “I wish I had red wings like you, Mama,” she cried.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 4, $$So one day, to cheer her up, Lara’s mother painted her wings bright red.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 5, $$The next morning, nobody greeted Lara on her way to school.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 6, $$And when she got there, none of her friends said hello.$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 7, $$Lara sat all alone. No one noticed her new red wings. Until Miss Miya spotted her and said: “You’ve painted your lovely yellow wings! ”$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 8, $$Lara’s classmates were shocked. “Your wings are special! ” “So unique! ”“So rare! ”$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 9, $$“Lara,” Miss Miya said, “your yellow wings are what make you you. Like Sipho’s spot … and Sally’s legs. ”$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 10, $$Back home, Lara took a long bath and scrubbed until her golden wings gleamed. “I’ll never paint my wings again! ” she thought. Except, maybe once or twice …$$),
    ('9c9f566e-fe46-11e5-86aa-5e5517507c66', 11, $$To try a bit of purple … or something nice. But not for ever and just for fun.$$)
  ) AS v(source_id, page_index, text)
  JOIN books b
    ON b.source_platform = 'book_dash' AND b.source_id = v.source_id
ON CONFLICT (book_id, page_index) DO NOTHING;

-- ───────── [적재검증] 트랜잭션 안 ─────────
-- (c) 적재 후 행 수 — 기대 469
