  WHERE NOT EXISTS (SELECT 1 FROM books b
     WHERE b.source_platform='book_dash' AND b.source_id=v.source_id);
-- (e) source 라벨 분포 — 기대 html_scene_json_v1 1종 / 469행
SELECT bt.source, count(*) FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='book_dash' AND b.source_id IN ('9c9e55de-fe46-11e5-86aa-5e5517507c66', '9c9e596c-fe46-11e5-86aa-5e5517507c66', '9c9e5f48-fe46-11e5-86aa-5e5517507c66', '9c9e6196-fe46-11e5-86aa-5e5517507c66', '9c9e62ea-fe46-11e5-86aa-5e5517507c66', '9c9e640c-fe46-11e5-86aa-5e5517507c66', '9c9e6524-fe46-11e5-86aa-5e5517507c66', '9c9e663c-fe46-11e5-86aa-5e5517507c66', '9c9e6754-fe46-11e5-86aa-5e5517507c66', '9c9e6d12-fe46-11e5-86aa-5e5517507c66', '9c9e6e52-fe46-11e5-86aa-5e5517507c66', '9c9e6f9c-fe46-11e5-86aa-5e5517507c66', '9c9e71cc-fe46-11e5-86aa-5e5517507c66', '9c9e72e4-fe46-11e5-86aa-5e5517507c66', '9c9e76ea-fe46-11e5-86aa-5e5517507c66', '9c9e7820-fe46-11e5-86aa-5e5517507c66', '9c9e7a6e-fe46-11e5-86aa-5e5517507c66', '9c9e7b9a-fe46-11e5-86aa-5e5517507c66', '9c9e7cb2-fe46-11e5-86aa-5e5517507c66', '9c9e7dca-fe46-11e5-86aa-5e5517507c66', '9c9e819e-fe46-11e5-86aa-5e5517507c66', '9c9e83b0-fe46-11e5-86aa-5e5517507c66', '9c9e8586-fe46-11e5-86aa-5e5517507c66', '9c9e86da-fe46-11e5-86aa-5e5517507c66', '9c9e87f2-fe46-11e5-86aa-5e5517507c66', '9c9e8c0c-fe46-11e5-86aa-5e5517507c66', '9c9e9102-fe46-11e5-86aa-5e5517507c66', '9c9e9396-fe46-11e5-86aa-5e5517507c66', '9c9e94e0-fe46-11e5-86aa-5e5517507c66', '9c9e96ac-fe46-11e5-86aa-5e5517507c66', '9c9e9e5e-fe46-11e5-86aa-5e5517507c66', '9c9e9fc6-fe46-11e5-86aa-5e5517507c66', '9c9ea21e-fe46-11e5-86aa-5e5517507c66', '9c9ea48a-fe46-11e5-86aa-5e5517507c66', '9c9ea96c-fe46-11e5-86aa-5e5517507c66', '9c9eb2cc-fe46-11e5-86aa-5e5517507c66', '9c9eb68c-fe46-11e5-86aa-5e5517507c66', '9c9f3292-fe46-11e5-86aa-5e5517507c66', '9c9f566e-fe46-11e5-86aa-5e5517507c66')
  GROUP BY bt.source;
-- (f) page_index 축 검증 — 권마다 0부터 연속이어야 한다. 기대 0행(위반 없음)
SELECT b.source_id, min(bt.page_index) AS mn, max(bt.page_index) AS mx, count(*) AS n
  FROM book_text bt JOIN books b ON b.id=bt.book_id
  WHERE b.source_platform='book_dash' AND b.source_id IN ('9c9e55de-fe46-11e5-86aa-5e5517507c66', '9c9e596c-fe46-11e5-86aa-5e5517507c66', '9c9e5f48-fe46-11e5-86aa-5e5517507c66', '9c9e6196-fe46-11e5-86aa-5e5517507c66', '9c9e62ea-fe46-11e5-86aa-5e5517507c66', '9c9e640c-fe46-11e5-86aa-5e5517507c66', '9c9e6524-fe46-11e5-86aa-5e5517507c66', '9c9e663c-fe46-11e5-86aa-5e5517507c66', '9c9e6754-fe46-11e5-86aa-5e5517507c66', '9c9e6d12-fe46-11e5-86aa-5e5517507c66', '9c9e6e52-fe46-11e5-86aa-5e5517507c66', '9c9e6f9c-fe46-11e5-86aa-5e5517507c66', '9c9e71cc-fe46-11e5-86aa-5e5517507c66', '9c9e72e4-fe46-11e5-86aa-5e5517507c66', '9c9e76ea-fe46-11e5-86aa-5e5517507c66', '9c9e7820-fe46-11e5-86aa-5e5517507c66', '9c9e7a6e-fe46-11e5-86aa-5e5517507c66', '9c9e7b9a-fe46-11e5-86aa-5e5517507c66', '9c9e7cb2-fe46-11e5-86aa-5e5517507c66', '9c9e7dca-fe46-11e5-86aa-5e5517507c66', '9c9e819e-fe46-11e5-86aa-5e5517507c66', '9c9e83b0-fe46-11e5-86aa-5e5517507c66', '9c9e8586-fe46-11e5-86aa-5e5517507c66', '9c9e86da-fe46-11e5-86aa-5e5517507c66', '9c9e87f2-fe46-11e5-86aa-5e5517507c66', '9c9e8c0c-fe46-11e5-86aa-5e5517507c66', '9c9e9102-fe46-11e5-86aa-5e5517507c66', '9c9e9396-fe46-11e5-86aa-5e5517507c66', '9c9e94e0-fe46-11e5-86aa-5e5517507c66', '9c9e96ac-fe46-11e5-86aa-5e5517507c66', '9c9e9e5e-fe46-11e5-86aa-5e5517507c66', '9c9e9fc6-fe46-11e5-86aa-5e5517507c66', '9c9ea21e-fe46-11e5-86aa-5e5517507c66', '9c9ea48a-fe46-11e5-86aa-5e5517507c66', '9c9ea96c-fe46-11e5-86aa-5e5517507c66', '9c9eb2cc-fe46-11e5-86aa-5e5517507c66', '9c9eb68c-fe46-11e5-86aa-5e5517507c66', '9c9f3292-fe46-11e5-86aa-5e5517507c66', '9c9f566e-fe46-11e5-86aa-5e5517507c66')
  GROUP BY b.source_id HAVING min(bt.page_index) <> 0 OR max(bt.page_index) <> count(*)-1;
-- (g) 빈 면 행 수 — 기대 1 (D7: 빈 면도 text='' 로 적재)
